// ==UserScript==
// @author       Journey Over
// @exclude      *
// ==UserLibrary==
// @name         @journeyover/animeapi
// @description  AnimeAPI v3 client for fetching anime relations across 22 providers
// @license      MIT
// @version      1.3.0
// @homepageURL  https://github.com/StylusThemes/Userscripts
// ==/UserLibrary==
// @connect      animeapi.my.id
// @grant        GM_xmlhttpRequest
// ==/UserScript==

this.AnimeAPI=class AnimeAPI{static PROVIDER_ALIASES={anidb:['ad','adb','anidb.net'],anilist:['al','anilist.co'],animenewsnetwork:['an','ann','animenewsnetwork.com'],animeplanet:['ap','anime-planet','anime-planet.com','animeplanet.com'],anisearch:['as','anisearch.com','anisearch.de','anisearch.it','anisearch.es','anisearch.fr','anisearch.jp'],annict:['ac','anc','act','annict.com','annict.jp','en.annict.com'],hikka:['hk','hka','hikka.io'],imdb:['im','imdb.com'],kaize:['kz','kaize.io'],kitsu:['kt','kts','kitsu.io','kitsu.app'],letterboxd:['lb','lx','letterboxd.com'],livechart:['lc','livechart.me'],myanimelist:['ma','mal','myanimelist.net'],nautiljon:['nj','ntj','nautiljon.com'],notify:['nf','ntf','ntm','notifymoe','notify.moe'],otakotaku:['oo','otakotaku.com'],shikimori:['sh','shiki','shk','shiki.one','shikimori.io','shikimori.me','shikimori.one','shikimori.org'],shoboi:['sb','shb','syb','shobocal','syoboi','syobocal','cal.syoboi.jp'],silveryasha:['sy','dbti','db.silveryasha.id','db.silveryasha.web.id'],simkl:['sm','smk','simkl.com','animecountdown','animecountdown.com'],themoviedb:['tm','tmdb','themoviedb.org'],thetvdb:['tv','tvdb','thetvdb.com','tvtime','tt','tvtime.com'],trakt:['tr','trk','trakt.tv']};static SOURCE_LOOKUP=AnimeAPI._buildSourceLookup();static _buildSourceLookup(){const lookup=new Map;for(const[canonical,aliases]of Object.entries(AnimeAPI.PROVIDER_ALIASES)){if(lookup.has(canonical))throw new Error(`Duplicate AnimeAPI provider alias: ${canonical}`);lookup.set(canonical,canonical);for(const alias of aliases){if(lookup.has(alias))throw new Error(`Duplicate AnimeAPI provider alias: ${alias}`);lookup.set(alias,canonical)}}return lookup}constructor(){this._mappingCache=new Map;this._mappingPending=new Map;this._mappingGeneration=0}_normalizeSource(source){const key=String(source).trim().toLowerCase();return AnimeAPI.SOURCE_LOOKUP.get(key)||key}_buildUrl(source,id){const canonical=this._normalizeSource(source);let idString=String(id);if(canonical==='thetvdb'&&!idString.toLowerCase().startsWith('series/')){idString=`series/${idString}`}const encodedId=idString.split('/').map(function(seg){return encodeURIComponent(seg)}).join('/');return`https://animeapi.my.id/${canonical}/${encodedId}`}fetch(source,id){if(!source)throw new Error('A source is required');if(!id)throw new Error('An ID is required');const url=this._buildUrl(source,id);return new Promise((resolve,reject)=>{GM_xmlhttpRequest({method:'GET',url:url,timeout:15e3,onload:response=>{if(response.status===404){resolve(null);return}if(response.status!==200){reject(new Error(`AnimeAPI request failed with status ${response.status}`));return}try{const data=JSON.parse(response.responseText);resolve(data)}catch{reject(new Error('Failed to parse AnimeAPI response'))}},onerror:()=>{reject(new Error('An error occurs while processing the request'))},ontimeout:()=>{reject(new Error('Request times out'))}})})}async fetchCached(source,id,{positiveTtl:positiveTtl=864e5,negativeTtl:negativeTtl=18e5}={}){if(!this._mappingCache)this._mappingCache=new Map;if(!this._mappingPending)this._mappingPending=new Map;if(typeof this._mappingGeneration!=='number')this._mappingGeneration=0;const key=`${source}:${id}`;const entry=this._mappingCache.get(key);if(entry&&entry.expiresAt>Date.now())return entry.value;if(this._mappingPending.has(key))return this._mappingPending.get(key);const generation=this._mappingGeneration;const pending=this.fetch(source,id).then(data=>{if(generation===this._mappingGeneration){this._mappingCache.set(key,{value:data,expiresAt:Date.now()+(data?.myanimelist||data?.anilist?positiveTtl:negativeTtl)})}if(this._mappingPending.get(key)===pending)this._mappingPending.delete(key);return data},error=>{if(this._mappingPending.get(key)===pending)this._mappingPending.delete(key);throw error});this._mappingPending.set(key,pending);return pending}async resolveFirst(candidates){let lastError=null;for(const candidate of candidates||[]){try{const data=await this.fetchCached(candidate.source,candidate.id);const mal=data?.myanimelist?Number(data.myanimelist):null;if(!mal)continue;return{source:candidate.source,id:candidate.id,label:candidate.label,data:data,mal:mal,anilist:data?.anilist?Number(data.anilist):null}}catch(error){lastError=error}}if(lastError)throw lastError;return null}clearMappingCache(){const count=this._mappingCache?this._mappingCache.size:0;this._mappingGeneration=(typeof this._mappingGeneration==='number'?this._mappingGeneration:0)+1;if(this._mappingCache)this._mappingCache.clear();if(this._mappingPending)this._mappingPending.clear();return count}};
